  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ben", "share": "50.00"})).toBe(true);
  expect(await ui.addPool(pg_uma, "P2")).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P2", {"member": "Cam", "share": "100.00"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "pool:P2", "share": "10.00"})).toBe(true);
  expect(await ui.addCrew(pg_uma, "C1", "Cam")).toBe(true);
  expect(await ui.inlineGrade(pg_uma, p_ada, "A")).toBe(true);
  expect(await ui.statementAsOf(pg_uma, p_ben, "2026-03-05")).toBe(false);
  const c_ben_0 = ui.must(await ui.quickAdd(pg_uma, {"name": "Ben", "amount": "12.50"}, p_ben));
  expect(await ui.statementAsOf(pg_uma, p_cam, "2026-03-28")).toBe(false);
  expect(await ui.hold(pg_uma, p_cam, {"from": "2026-02-25", "to": "2026-03-28"})).toBe(true);
  expect(await ui.claimEditOpen(pg_uma, c_ben_0)).toBe(true);
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  expect(await ui.claimEditOpen(pg_vic, c_ben_0)).toBe(false);
  await ui.refresh(pg_uma);
  expect(await ui.claimEditSave(pg_uma, c_ben_0, {"amount": "12.50"})).toBe(true);
  expect(await ui.editClaim(pg_uma, c_ben_0, {"date": "2026-03-09"})).toBe(true);
  await ui.refresh(pg_uma);
  expect(await ui.hold(pg_uma, p_cam, {"from": "2026-03-05", "to": "2026-03-28"})).toBe(true);
  expect(await ui.search(pg_uma, "zz")).toEqual([]);
