  expect(await ui.inlineGrade(pg_vic, p_ada, "B")).toBe(true);
  expect(await ui.periodAction(pg_vic, "P2", "close")).toBe(true);
  expect(await ui.editInline(pg_vic, c_ben_0, "4.00")).toBe(false);

